/* 头像移动到气泡上方 */
.mes {
    position: relative;
    margin-top: 60px !important; /* 为头像预留空间 */
    padding-top: 20px !important; /* 顶部内间距 */
}

.mesAvatarWrapper {
    position: absolute;
    top: -70px; /* 上移超出气泡容器 */
    left: 90%;
    transform: translateX(-50%);
    z-index: 1;
    width: 100%;
    text-align: center;
}

/* 调整头像尺寸 */
.avatar img {
    width: 60px !important;
    height: 60px !important;
    border-radius: 50%;
    important;
}


/* 头像上方新增装饰图标 */
.mesAvatarWrapper {    
}

/* 装饰图标容器 */
.mesAvatarWrapper::before {
    content: "";
    position: absolute;
    top: -14px; /* 位于头像上方 */
    left: 11%;
    transform: translateX(-50%);
    width: 77px;
    height: 77px;
    background-image: url("https://files.catbox.moe/w8dxcj.gif"); /* 替换为实际图片URL */
    background-size: contain;
    background-repeat: no-repeat;
    filter: drop-shadow(0 2px 4px rgba(131, 109, 96, 0.3));
    z-index: 4; /* 确保在最顶层 */
    pointer-events: none;
    animation: glow 2s ease-in-out infinite alternate;
}


/* 聊天气泡居中 */
#chat {
    display: flex;
    flex-direction: column;
    align-items: center; /* 新增居中关键属性 */
