/* 暖棕米杏配色方案 */
:root {
  --tab-bg: rgba(252, 242, 231, 1);       /* 主背景米杏色 #FCF2E7 半透明 */
  --tab-border: rgba(225, 199, 176, 0.6);    /* 暖棕粉边框 #E1C7B0 半透明 */
  --tab-active-bg: #E1C7B0;                  /* 激活状态暖棕粉（纯色色块） */
  --tab-shadow: rgba(160, 140, 150, 0.1);     /* 保留原有柔灰阴影（可根据需求微调） */
}

.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
  background: 
    linear-gradient(175deg, 
      var(--tab-bg) 20%,           /* 米杏色起始 */
      var(--tab-active-bg) 100%     /* 暖棕粉最终色（原120%调整为100%避免溢出） */
    ) !important;
  border: 1px solid var(--tab-border) !important;
  box-shadow: 
    0 2px 4px var(--tab-shadow),
    inset 0 1px 1px rgba(255, 255, 255, 0.4),
    inset 0 -1px 2px rgba(225, 199, 176, 0.2) !important;  
  border-radius: 20px;
  backdrop-filter: blur(3px);
}


.inline-drawer-toggle.inline-drawer-header:hover,
.inline-drawer-toggle.inline-drawer-header:focus {
  background: 
    linear-gradient(175deg, 
      var(--tab-active-bg) 30%,     
      var(--tab-bg) 100%            /*  */
    ) !important;
  box-shadow: 
    0 3px 6px rgba(160, 140, 150, 0.15),
    inset 0 1px 4px rgba(255, 255, 255, 0.5) !important;
}


:root {
  /* 新增下拉框专用变量（可复用主配色变量） */
  --select-bg: var(--tab-bg);         /* 下拉框背景（米杏色） */
  --select-border: var(--tab-border); /* 边框（暖棕粉半透明） */
  --select-active-bg: var(--tab-active-bg); /* 激活/悬停背景（纯暖棕粉） */
  --select-shadow: var(--tab-shadow); /* 阴影（柔灰） */
  --select-arrow-color: #E1C7B0;      /* 下拉箭头颜色（暖棕粉） */
}

/* 基础下拉框样式 */
.select-container {
  position: relative;
  display: inline-block;
  width: 100px; /* 可自定义宽度 */
}

select {
  width: 100%;
  padding: px 32px 8px 12px; /* 留出箭头空间 */
  font-size: 14px;
  background: var(--select-bg);
  border: 1px solid var(--select-border);
  border-radius: 8px;
  box-shadow: 0 2px 4px var(--select-shadow),
             inset 0 1px 2px rgba(255, 255, 255, 0.4);
  appearance: none; /* 去除默认箭头 */
  cursor: pointer;
}

/* 自定义下拉箭头（伪元素） */
select::after {
  content: "";
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 0;
  height: 0;
  border: 6px solid transparent;
  border-top-color: var(--select-arrow-color); /* 箭头颜色 */
}


### 3. 交互状态样式（悬停/聚焦/激活）
```css
/* 悬停/聚焦状态 */
select:hover,
select:focus {
  background: linear-gradient(175deg, 
    var(--select-active-bg) 20%,  /* 暖棕粉起始 */
    var(--select-bg) 100%         /* 米杏色收尾 */
  );
  border-color: var(--select-active-bg); /* 边框加深为纯暖棕粉 */
  box-shadow: 0 3px 6px rgba(160, 140, 150, 0.15),
             inset 0 1px 4px rgba(255, 255, 255, 0.5);
  outline: none; /* 去除浏览器默认聚焦环 */
}

/* 下拉菜单（option）样式 */
select option {
  padding: 8px 12px;
  background: var(--select-bg); /* 选项背景保持米杏色 */
  color: #333;
}

/* 选项悬停状态 */
select option:hover {
  background: linear-gradient(175deg, 
    rgba(225, 199, 176, 0.1) 20%,  /* 暖棕粉浅透明渐变 */
    var(--select-bg) 100%
  );
}

/* 禁用状态（可选） */
select:disabled {
  opacity: 0.7;
  cursor: not-allowed;
}






